import{_ as e,H as a,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"22-为什么压力测试TPS总是上不去？","description":"","frontmatter":{},"headers":[{"level":2,"title":"压测要做什么？","slug":"压测要做什么","link":"#压测要做什么","children":[]},{"level":2,"title":"案例 1：压测 TPS 上不去","slug":"案例-1-压测-tps-上不去","link":"#案例-1-压测-tps-上不去","children":[{"level":3,"title":"性能工具 sar","slug":"性能工具-sar","link":"#性能工具-sar","children":[]}]},{"level":2,"title":"案例 2：LoadRunner 压测发现部分失败","slug":"案例-2-loadrunner-压测发现部分失败","link":"#案例-2-loadrunner-压测发现部分失败","children":[]},{"level":2,"title":"案例 3：压测报 cannot assign requested address 错误","slug":"案例-3-压测报-cannot-assign-requested-address-错误","link":"#案例-3-压测报-cannot-assign-requested-address-错误","children":[]},{"level":2,"title":"案例 4：压测遇到 connection reset by peer","slug":"案例-4-压测遇到-connection-reset-by-peer","link":"#案例-4-压测遇到-connection-reset-by-peer","children":[]},{"level":2,"title":"实验","slug":"实验","link":"#实验","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"附录","slug":"附录","link":"#附录","children":[]}],"relativePath":"网络排查案例课/22-为什么压力测试TPS总是上不去？.md","filePath":"网络排查案例课/22-为什么压力测试TPS总是上不去？.md","lastUpdated":1795563497000}'),i={name:"网络排查案例课/22-为什么压力测试TPS总是上不去？.md"};function p(E,s,l,B,o,c){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="_22-为什么压力测试tps总是上不去" tabindex="-1">22-为什么压力测试TPS总是上不去？ <a class="header-anchor" href="#_22-为什么压力测试tps总是上不去" aria-label="Permalink to &quot;22-为什么压力测试TPS总是上不去？&quot;">​</a></h1><p>你好，我是胜辉。</p><p>在上一讲里，我们排查了一个跟操作系统紧密相关的性能问题。我们结合 top 和 strace 这两个工具，抓住了关键点，从而解决了问题。性能问题，确实也是我们日常技术工作中的一个重要话题。在出现性能问题以后，我们要有能力搞定它；而在出现性能问题之前，最好能提前预见到它。而要“预见”性能瓶颈，最好的方法就是做压力测试。</p><p>但是，我们在做压力测试的过程中也时常出现预料不到的情况。比如在离预期的瓶颈值还很远的时候，系统就出现了各种意外，影响到压力测试的继续进行。</p><p>那么在这节课里，我们会回顾几个典型的压力测试场景中的网络问题，一起来学习其中的关键要点。同时，我们还会学习一系列跟网络性能相关的压测工具和检测工具，这样以后你遇到类似的问题时，就有所准备了。</p><h2 id="压测要做什么" tabindex="-1">压测要做什么？ <a class="header-anchor" href="#压测要做什么" aria-label="Permalink to &quot;压测要做什么？&quot;">​</a></h2><p>压力测试的诉求实际上多种多样，不过大体上可以分为这几种。</p><p>应用的承受能力：这主要在第七层应用层，比如发起了压测，把服务端的 CPU 打到 95% 甚至 100%，观察这时候的请求的 TPS、请求耗时、并发量等等。而这些对于不同的业务场景，又会有不同的侧重点。比如：</p><ul><li><p>对于时间敏感型业务来说，请求耗时（Latency）这个指标就是关键了。</p></li><li><p>对于经常做秒杀的电商来说，并发处理量 TPS（Transaction Per Second）就是一个核心关注点了。</p></li></ul><p>LB 的连接处理能力：这主要在第四层 TCP，看 LB 能最大支持的 TCP 并发连接数。这时候，发起压测的客户端一般会指定比较大的并发数，这样就可以发起尽量多的 TCP 连接。</p><p>网络的承受能力：这可能主要在第三层 IP 层了，比如测试上行和下行带宽能否跑满、是否有丢包和额外的延迟，等等。特别是对于一些流量比较大的场景，很可能服务端计算能力都还在，但带宽已经不够用了，所以我们要提前发现这些隐患。</p><h2 id="案例-1-压测-tps-上不去" tabindex="-1">案例 1：压测 TPS 上不去 <a class="header-anchor" href="#案例-1-压测-tps-上不去" aria-label="Permalink to &quot;案例 1：压测 TPS 上不去&quot;">​</a></h2><p>我们有个客户是传统企业转型做电商，有一次准备搞大促。为了确保大促顺利，他们要提前对网站进行压测。</p><p>客户用的压测工具比较简单，是 Apache ab。ab 是 Apache Benchmark 的缩写，它的用途就是对 HTTP 服务端发起测试，以获得性能指标（Benchmark）。ab 本身不是独立安装的，而是在 apache2-utils 工具包里，所以你可以这样来安装它：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apache2-utils</span></span></code></pre></div><p>ab 是一个轻量级的工具，因为相对其他重量级的工具比如 LoadRunner 或者 JMeter 来说，ab只要一行命令就可以发起压测了，是不是很省事？比如你可以这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ab -c 100 -n 10000 目标URL</span></span></code></pre></div><p>通过上面的命令，你就用 -c 100 这个参数，让 ab 发起了 100 个并发的请求，而 -n 10000 指定了总共发送的请求量。</p><ul><li>补充：这里有一个小的注意点。如果目标 URL 只是站点名本身，还是需要在结尾处加</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上“&gt;/”，要不然 ab 会报这个错误：ab: invalid URL</span></span></code></pre></div><p>比如我用下面这条 ab 命令，对一个著名网站发起“压测”，当然我的参数选择的很小，只有 10个并发，一共 100 次请求，尽量避免打扰到这个网站。我们可以看一下输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ab -c 10 -n 100 https://www.baidu.com/abc</span></span>
<span class="line"><span>This is ApacheBench, Version 2.3 &lt;$Revision: 1843412 $&gt;</span></span>
<span class="line"><span>Copyright 1996 Adam Twiss, Zeus Technology Ltd, http://www.zeustech.net/</span></span>
<span class="line"><span>Licensed to The Apache Software Foundation, http://www.apache.org/</span></span>
<span class="line"><span>Benchmarking www.baidu.com (be patient).....done</span></span>
<span class="line"><span>Server Software:        Apache</span></span>
<span class="line"><span>Server Hostname:        www.baidu.com</span></span>
<span class="line"><span>Server Port:            443</span></span>
<span class="line"><span>SSL/TLS Protocol:       TLSv1.2,ECDHE-RSA-AES128-GCM-SHA256,2048,128</span></span>
<span class="line"><span>Server Temp Key:        ECDH P-256 256 bits</span></span>
<span class="line"><span>TLS Server Name:        www.baidu.com</span></span>
<span class="line"><span>Document Path:          /abc</span></span>
<span class="line"><span>Document Length:        201 bytes</span></span>
<span class="line"><span>Concurrency Level:      10</span></span>
<span class="line"><span>Time taken for tests:   9.091 seconds</span></span>
<span class="line"><span>Complete requests:      100</span></span>
<span class="line"><span>Failed requests:        0</span></span>
<span class="line"><span>Non-2xx responses:      100</span></span>
<span class="line"><span>Total transferred:      34600 bytes</span></span>
<span class="line"><span>HTML transferred:       20100 bytes</span></span>
<span class="line"><span>Requests per second:    11.00 [#/sec] (mean)</span></span>
<span class="line"><span>Time per request:       909.051 [ms] (mean)</span></span>
<span class="line"><span>Time per request:       90.905 [ms] (mean, across all concurrent requests)</span></span>
<span class="line"><span>Transfer rate:          3.72 [Kbytes/sec] received</span></span>
<span class="line"><span>Connection Times (ms)</span></span>
<span class="line"><span>             min  mean[+/-sd] median   max</span></span>
<span class="line"><span>Connect:      141  799 429.9    738    4645</span></span>
<span class="line"><span>Processing:    19   67 102.0     23     416</span></span>
<span class="line"><span>Waiting:       17   67 101.8     23     416</span></span>
<span class="line"><span>Total:        162  866 439.7    796    4666</span></span>
<span class="line"><span>Percentage of the requests served within a certain time (ms)</span></span>
<span class="line"><span> 50%    796</span></span>
<span class="line"><span> 66%    877</span></span>
<span class="line"><span> 75%    944</span></span>
<span class="line"><span> 80%   1035</span></span>
<span class="line"><span> 90%   1093</span></span>
<span class="line"><span> 95%   1339</span></span>
<span class="line"><span> 98%   1530</span></span>
<span class="line"><span> 99%   4666</span></span>
<span class="line"><span>100%   4666 (longest request)</span></span></code></pre></div><p>结尾部分的多个 Percentage，确切地说就是 Percentile，也就是百分位。比如 50% 796 这一行的意思是：第 50 个请求（因为总数是 100 个）的耗时小于等于 796 毫秒，另外 50 个请求大于 796 毫秒。那么我们也可以知道，耗时最长的那个就是排最后一名的 4666，它的耗时是4666 毫秒。</p><p>这次，客户用 ab 时指定的具体参数是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ab -k -c 500 -n 100000 http://site.name.com/path</span></span></code></pre></div><p>也就是并发数为 500，总次数为 10 万，而 -k 参数是启用长连接。然后就是查看以下两个主要指标：</p><ul><li><p>ab 这个客户端的耗时分布，也就是前面刚介绍过的各个百分位的耗时数值。</p></li><li><p>服务端的性能指标，也就是在这个压力下面，服务端的 CPU、内存、网络丢包率等的统计数值。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/1.png" alt=""></a></p><p>压测过程中，客户发现测试端的带宽用到 400Mbps 后，TPS 就上不去了，无论把并发量或者总量的数值进行怎样的调整，TPS 都会维持在一个稳定的数值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transfer rate:          52087.82 [Kbytes/sec] received</span></span></code></pre></div><p>那究竟是不是购买的服务端主机的性能不够的原因呢？要知道，客户端和服务端都是 1Gbps的网卡，客户是想压满 100% 的带宽，现在只用到了 40% 的带宽，TPS 就上不去了。</p><p>为什么会这样呢？</p><p>我们就跟客户配合，一边做 ab 压测，一边做了 4 秒钟的 tcpdump 抓包，这对采样分析来说也够用了。然后打开抓包文件，查看专家信息（Expert Information），如下：</p><ul><li>补充：抓包示例文件已经上传至Gitee，建议结合抓包文件和文稿一起学习。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/2.png" alt=""></a></p><p>这次我就不做标记了，你自己先找找看，能否找到一些问题？</p><p>你有没有发现，GET 有 1603 次（倒数第三行），而 RST 有 1982 次（第三行），比 GET 这种HTTP 请求的次数还更多。也就是说，平摊的话，每次 GET 请求对应了一次以上的 RST。这个现象会不会跟 TPS 上不去的问题有关系呢？</p><p>我们选一个 RST 来看一下情况。比如 14031 号报文：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/3.png" alt=""></a></p><p>然后 Follow -&gt; TCP Stream，就来到了这条 TCP 流：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/4.png" alt=""></a></p><p>在这里，你有没有发现两个重传报文？一个是 6504 号报文，一个是 7340 号报文。我们再进一步看一下这两个的重传的原因是什么。一般来说，判断一个报文是否是重传，最方便的就是借助 Wireshark 本身提供的提示，Wireshark 说是 Retransmission，那就是了。</p><p>那么假设世界上还没有 Wireshark，你又如何判断一个报文是否是重传呢？其实可以根据两个关键信息：序列号、载荷长度。</p><p>我在之前的课程里提到过，序列号本身反映的就是字节位置，载荷的长度就表示这段报文的实际字节长度，这两个信息就确定了信息的起点和终点，也就是决定了一个报文是否是之前报文的重传。</p><p>在上面的截图里，我们根据序列号（Sequence Number 列）和载荷长度（TCP Seglen 列），判断出下面两次重传：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/5.png" alt=""></a></p><p>可见，7340 是 3155 报文的重传，因为它们的序列号都是 9593，载荷长度都是 1061。同样的道理，6504 和 3156 也是一对重传关系。</p><p>当然，我们也可以直接在 Wireshark 里选中 7340 号报文，它的基础报文也就是 3155 的前面会出现一个小圆点，就像下图这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/6.png" alt=""></a></p><p>总之，我们确认 TCP 传输中是有丢包和重传现象的，我们可以回头从专家信息那里得到证实，这里显示有 184 个 Suprious 重传和 2274 个（超时）重传。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/7.png" alt=""></a></p><ul><li>补充：而出现 RST 的原因，是客户端在已经没有了这个 TCP 连接的情况下，收到了服务端的 ACK 报文。从现象来看，客户端应该是做了 TIME_WAIT 优化的设置，我们后面的实验里也会带到。</li></ul><p>考虑到这是在压测场景中出现的丢包现象，我们根据经验，想到了网卡包量的问题。</p><p>一般说到网络性能，我们会讨论的就是带宽、时延、网速等等这些指标。实际上，另外一个性能指标常常在达到带宽极限之前就已经触顶了，它就是包量。</p><p>包量是对 PPS（Packet Per Second）的简称，一般用来衡量一台主机的网络处理能力。那么，这次是不是触及了服务端主机的包量上限了呢？我们又如何检查包量指标呢？</p><p>我们需要用的工具是 sar。</p><h3 id="性能工具-sar" tabindex="-1">性能工具 sar <a class="header-anchor" href="#性能工具-sar" aria-label="Permalink to &quot;性能工具 sar&quot;">​</a></h3><p>sar 是 sysstat 工具集的一部分。这个工具集包含了一些很有用的工具，除了 sar，还有mpstat、iostat 等等。如果你平时经常做操作系统维护方面的工作，应该对它们比较熟悉了。这些工具还有一个共同的特点，运行的时候一般都是加上“间隔 次数”这样的参数的。也就是下面这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sar -n DEV 1 10   #查看网卡性能</span></span>
<span class="line"><span>iostat 1 10       #查看IO性能</span></span>
<span class="line"><span>mpstat 2 5        #查看CPU性能</span></span></code></pre></div><p>这些工具会按指定的时间间隔，运行指定的次数后再退出。这样我们就可以观察到这段时间内的多次输出了，很适合通过这种多次的观察，得到比较准确的性能数据趋势。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这次我们也在被压测的服务端云主机上运行了 sar -n DEV，得到了以下的性能数据：</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/8.png" alt=""></a></p><p>前面说的包量，就是体现在两个 pck/s 指标中，一个是 rxpck/s，就是接收方向的包量；一个是 txpck/s，就是发送方向的包量。显然，图中的数值已经在 5 万左右，这个正是当时我们云主机性能的上限。难怪服务端已经无法提供更高的 TPS 了，因为网络包的处理都来不及做了。</p><p>那你可能会问了：“网络包也有大有小，这个包量指标说的是大包还是小包呢？”</p><p>其实，一般的包量测试，不是随便什么大小的报文都可以测试，而是普遍使用 64 字节长度的IP 报文。另外，我们也要认识到，包的大小对包量性能的影响也不是很大。这是因为，对于网络处理来说，主要的开销在包的头部的处理上，而载荷本身的处理是很快的。</p><p>那么，对于客户遇到的这种包量达到上限的情况，我们可以选择的应对办法是这样的：</p><ul><li><p>选择更高网络性能的主机，比如硬件的 RSS、软件的 RPS 等特性，都会大幅提升包量处理性能。</p></li><li><p>对服务集群进行水平扩展，也就是在 LB 后面增加服务器，这样 VIP 作为一个整体提供的包，处理能力也就提升了。</p></li></ul><h2 id="案例-2-loadrunner-压测发现部分失败" tabindex="-1">案例 2：LoadRunner 压测发现部分失败 <a class="header-anchor" href="#案例-2-loadrunner-压测发现部分失败" aria-label="Permalink to &quot;案例 2：LoadRunner 压测发现部分失败&quot;">​</a></h2><p>这是另外一个客户，他们没有用 ab 这样的简单工具，而是用了 LoadRunner 这样一个企业级的测试软件。LoadRunner 的厉害之处在于，不仅可以发起巨大的请求量，而且可以模拟用户的复杂行为，比如登录、浏览、加入购物车等等。这一系列事务有前后状态关系，这就不是简单的 ab 可以做到的了。</p><p>但是测试结果中的小几十个 Failed 和 Error 引起了客户的疑虑。他们怀疑：是不是我们公有云的机器或者网络质量不行，所以才导致了这些失败呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/9.png" alt=""></a></p><p>我们就尝试复现这个压测场景，同时也对测试机上的 TCP 资源情况做检查，其中最主要的就是源端口了。</p><p>为什么会想到这个呢？因为压测发起的请求，都是依托于 TCP 连接的。我们在第 1 讲里就提到过：TCP 连接是基于五元组的。那么对于客户端来说，源 IP、目的 IP、目的端口、协议，这四个元素都不会变化，唯一会变的就是自己的源端口了。那么我们来看看，当时测试机的源端口情况。</p><p>这是一台 Window 机器，跟 Linux 类似，我们执行这条命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netstat -ant</span></span></code></pre></div><p>输出如下图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/10.png" alt=""></a></p><p>原来，确实有大量的 TCP 连接都在 TIME_WAIT 状态，尤其是源端口已经用到了 65534。所以可以肯定，这次压测中出现失败的原因，就在于源端口耗尽。</p><p>那要如何处理呢？显然我们也变不出更多的端口来。这个时候，我们可以调整压测软件的设置，比如从短连接改成长连接。这样就可以避免源端口耗尽的情况，因为所有的请求是在长连接里完成的，只要连接池本身设置合理，源端口就不会被用完。</p><h2 id="案例-3-压测报-cannot-assign-requested-address-错误" tabindex="-1">案例 3：压测报 cannot assign requested address 错误 <a class="header-anchor" href="#案例-3-压测报-cannot-assign-requested-address-错误" aria-label="Permalink to &quot;案例 3：压测报 cannot assign requested address 错误&quot;">​</a></h2><p>我们内部有一个团队在做业务压力测试，结果遇到了一个奇怪的报错：cannot assignrequested address。这次的场景是这样的：这个团队从多台客户端机器向 LB 上的一个 VIP，发送大量的请求，而 LB 的后面就是很多的服务器。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/11.png" alt=""></a></p><p>但是，还没等到这些服务器的负载跑起来，客户端那边提前报错了。这是一个 Go 语言的程序，具体的报错信息如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://test.vip/a&quot;: dial tcp 10.123.123.12:443: connect: cannot assign requested</span></span>
<span class="line"><span>http post Post \\&quot;https://test.vip/b&quot;: dial tcp 10.123.123.12:443: connect: cannot</span></span></code></pre></div><p>于是他们就怀疑：既然报错是连接出错，那是不是 LB 有什么问题呢？比如，是否 LB 本身处理能力不够，不能服务这么大量的连接请求？否则为什么客户端会报 connect 的错误呢？要知道，用来发起 TCP 连接的系统调用（syscall）就是 connect。</p><p>确实，这个报错信息“dial tcp 10.123.123.12:443: connect: cannot assign requestedaddress”说得不太清楚。表面上看，就是客户端往 10.123.123.12:443 这个 VIP 发起连接请求（用 connect）然后遇到了报错，也难怪测试团队会找到我们来查看 LB 的问题。</p><p>我们检查了 LB，发现一切正常。于是把排查方向换到客户端。在这次测试中，有一个参数是关于 HTTP Keep-alive 的。如果你对课程前面的内容还有印象的话，应该还记得我们在第 7讲“保活机制”里，深入讨论过这个问题。</p><p>简单来说，这次的测试配置里，HTTP Keep-alive 没有打开，导致这些 TCP 连接被视作短连接来处理了，也就是一次 HTTP 请求和响应完成后，这条连接就关闭了。由于发起关闭的是客户端自己，于是这条连接也就进入了 TIME_WAIT 状态。</p><p>而要查看 TIME_WAIT 状态的连接数量，我们可以用 netstat 命令，配合管道和 awk 来完成统计。比如，这次我在一台客户端机器上执行了下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ netstat -ant |awk &#39;{++a[$6]} END{for (i in a) print i, a[i]}&#39;</span></span>
<span class="line"><span>TIME_WAIT 28231</span></span></code></pre></div><p>或者用下面的 ss 命令会更快：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ss -ant | awk &#39;{++s[$1]}END{for(k in s) print k,s[k]}&#39;</span></span>
<span class="line"><span>TIME-WAIT 28231</span></span></code></pre></div><p>可见，处于 TIME_WAIT 状态的连接数接近 3 万个，差不多就是 Linux 的本地动态端口的范围了。我们随后检查这台 Linux 机器的本地源端口范围，执行了下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat /proc/sys/net/ipv4/ip_local_port_range</span></span>
<span class="line"><span>32768  60999</span></span></code></pre></div><p>于是发现它的下限是 32768，上限是 60999，范围正好就是 28231，跟 TIME_WAIT 的数量一致，显然也是一次源端口耗尽导致的压测问题。</p><p>当然，用 sysctl 也一样可以查看这个范围：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl net.ipv4.ip_local_port_range</span></span></code></pre></div><p>不过你可能会问：“难道压测中的网络排查，除了包量和源端口，就没有别的问题了吗？”</p><p>我们来看一个不一样的案例。</p><h2 id="案例-4-压测遇到-connection-reset-by-peer" tabindex="-1">案例 4：压测遇到 connection reset by peer <a class="header-anchor" href="#案例-4-压测遇到-connection-reset-by-peer" aria-label="Permalink to &quot;案例 4：压测遇到 connection reset by peer&quot;">​</a></h2><p>这次的场景是一个应用团队用 netty http client 去调用一个 VIP 做压测。具体来说是 9 台客户端机器，向同一个 LB VIP 发起大量的请求。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/12.png" alt=""></a></p><p>结果遇到了 connection reset by peer。蹊跷的是，这个报错是零零星星出现的。而像之前的例子，如果真的源端口用尽了，那么接下来一段时间内，这些请求都会因为本地没有源端口可用而宣告失败，也就是报错会是大面积出现，而不会零星出现。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/13.png" alt=""></a></p><p>从图上看，报错数量不超过 50 个，主要集中在 11 点 20 分到 11 点 35 分这个时间段，这正是压测的时段。因为报错只有 50 来个，这相比于这次压测发起的成千上万的请求来说，是很小的比例了。</p><ul><li>补充：Y 轴就是报错的个数，最高值是 10，我们把几个柱体的高度加起来，就是报错的总数量了。</li></ul><p>我们了解到，压测期间每个客户端的请求频率是 700TPS，所以 9 台客户端一共会发起6300TPS 的请求量。这个问题诡异的地方就是，大部分的请求都能得到正确及时的回复，但是隔了两三分钟，就会出现几次这种 connection reset by peer 的问题。</p><p>那我们需要理解一下，为什么会 reset。</p><p>我们在做网络排查的时候，如果在 Wireshark 里看到 TCP RST，往往会觉得它不是一个好的征兆。确实，有时候是 RST 引起了故障，有时候又是网络故障迫使 TCP 用 RST 来结束连接。无论 RST 是因还是果，它总是跟问题本身逃不脱关系。</p><p>那干脆在 TCP 里取消 RST，是不是很多问题就会被解决呢？当然不是，RST 在 TCP 里面是一个非常必要的组成部分。没有 RST，其实就没有“坏”的结束，也就没有“好”的开始。</p><p>大体上，TCP RST 的原因可以分为这么几个大类：</p><ul><li><p>找不到相关连接，那么接收端可以放心地直接发送 RST。</p></li><li><p>找到了相关连接，但收到的报文不符合 TCP 规范，那么接收端也可以发送 RST。</p></li><li><p>找到了相关连接，但传输状况恶劣，内核选择及时“止损”，发送 RST。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/14.png" alt=""></a></p><p>而这次案例里面的情况，就符合第一种。这是因为：</p><ul><li><p>我们的 LB 上的 VIP 有一个 idle timeout 的设置，如果客户端在一定时限内不发任何报文，那么这条连接将被回收。这个时限是 180 秒，而且回收时不向客户端发送 FIN 或者 RST 报文。</p></li><li><p>这次的压测客户端框架里，有一个设置值也是关于 idle timeout 的。不过这个值设置的是360 秒。</p></li></ul><p>你有没有发现问题？这两个 idle timeout 值一边大一边小，配合不当，就会出现下面这样的问题：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/22-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%258E%258B%25E5%258A%259B%25E6%25B5%258B%25E8%25AF%2595TPS%25E6%2580%25BB%25E6%2598%25AF%25E4%25B8%258A%25E4%25B8%258D%25E5%258E%25BB%25EF%25BC%259F/15.png" alt=""></a></p><p>某条 TCP 连接中完成一次 HTTP 请求和响应之后，连接没有被关闭。过了 180 秒，LB 这一侧的连接被回收了，但客户端那边还没到 360 秒，所以还认为这条连接是活着的，于是在 180秒之后发起了一次请求。报文到达 LB，后者在连接表里没有查到这条连接，于是回复了RST。</p><p>根因清楚了，解决起来异常简单：把客户端的 Idle timeout 参数，从原先的 360 秒，改成比LB 的 180 秒更低的值就好了。这次改到了 120 秒，RST 就完全消失了。</p><p>你看，虽然在案例 2 里，我们知道了压测最好使用长连接，这样可以避免源端口耗尽的问题。但是不等于你设置了长连接就一劳永逸了，还需要考虑 idle timeout 的问题。这次压测的关键在于：要确保长连接本身是真正有效的，你需要确保客户端的 idle timeout 小于服务端的 idletimeout，这样才能避免连接失效导致的 RST。</p><ul><li>补充：这个库是 Ractor-Netty，idle timeout 对应的是evictInBackground +maxLifeTime。</li></ul><h2 id="实验" tabindex="-1">实验 <a class="header-anchor" href="#实验" aria-label="Permalink to &quot;实验&quot;">​</a></h2><p>回顾完这些压测案例，你可能会发现其实难度并不太大，是不是也跃跃欲试了呢？接下来，我们就用 ab 来做个小实验，这次还捎带一个小任务：控制 TIME_WAIT 状态的连接的数量。</p><p>在案例 2 和 3 里面，源端口耗尽的问题，本质是 TIME_WAIT 需要停留 2MSL 的时长。要解决 TIME_WAIT 连接过多的问题，方法有很多。这次我们只实验其中的一种方法，就是修改</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net.ipv4.tcp_max_tw_buckets 这个内核参数。</span></span></code></pre></div><p>它的默认值为 16384，改为更小的值后，超过这个数值的 TIME_WAIT 连接会被清除，这样，TIME_WAIT 连接数就被控制住了。</p><p>这个实验在本地就可以完成，比如在你的笔记本上安装 VirtualBox，然后在这个虚拟机里面完成实验。</p><p>步骤一：安装 Nginx 和 Apache ab。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apache2-utils</span></span></code></pre></div><p>步骤二：启动 ab 测试，执行下面的命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ab -c 500 -n 10000 http://localhost/</span></span></code></pre></div><p>步骤三：观察 TCP 连接的各种状态的统计数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ss -ant | awk &#39;{++s[$1]}END{for(k in s) print k,s[k]}&#39;</span></span></code></pre></div><p>此时你应该会看到 1 万多个 TIME_WAIT 的连接，然后等待 2 分钟后继续步骤四。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>步骤四：修改内核参数 tcp_max_tw_buckets 为 100。</span></span>
<span class="line"><span>sysctl net.ipv4.tcp_max_tw_buckets=100</span></span></code></pre></div><p>步骤五：再次 ab 测试。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ab -c 500 -n 10000 http://localhost/</span></span></code></pre></div><p>步骤六：再次观察 TCP 连接的各种状态的统计数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ss -ant | awk &#39;{++s[$1]}END{for(k in s) print k,s[k]}&#39;</span></span></code></pre></div><p>此时 TIME_WAIT 应该只有 100 了。</p><p>当然，TIME_WAIT 本身被设计出来是有原因的，建议你在改动它之前，把自己的场景想清楚，然后再改不迟。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课，我们回顾了几个典型的压力测试场景中的网络问题，你需要重点掌握以下这些知识点。</p><p>关于压测指标和工具。轻量级的工具是 ab，它十分方便，而且也可以发起大量的请求，在简单的压测场景下很有用。比如下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ab -k -c 100 -n 10000 目标URL</span></span></code></pre></div><p>重量级工具是 LoadRunner 和 JMeter，它们可以实现复杂的交互行为，也提供更加详细的报告。</p><p>在网络性能领域，包量是对 PPS 的简称，一般用来衡量一台主机的网络处理能力。而评估包量的工具是 sar，我们可以运行下面的命令获取到实时的包量值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sar -n DEV 1 10</span></span></code></pre></div><p>关于 TCP 的知识。这节课里我们也再次温习了 TCP 相关的知识，包括：</p><ul><li><p>判断一个报文是否是之前报文的重传，可以根据两个关键信息：序列号、载荷长度。这两个值分别相同的多个报文，互相就是重传关系了。</p></li><li><p>压测数据起不来的一个常见原因是源端口耗尽，要验证这一点，可以执行以下命令，来查看TIME_WAIT 或者 ESTABLISHED 状态的连接数是否到达了上限：</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ss -ant | awk &#39;{++s[$1]}END{for(k in s) print k,s[k]}&#39;</span></span></code></pre></div><p>或者：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netstat -ant |awk &#39;{++a[$6]} END{for (i in a) print i, a[i]}&#39;</span></span></code></pre></div><ul><li>而连接数到达上限值的问题，往往跟可用的本地源端口范围有关。要查看端口范围，我们可以执行这条命令：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl net.ipv4.ip_local_port_range</span></span></code></pre></div><ul><li>压测中遇到 RST 的原因，可能跟两端的 idle timeout 不合理有关，建议把客户端的 idletimeout 设置为比服务端 idle timeout 更低的值。</li></ul><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后还是再给你留两道思考题：</p><ul><li><p>测试 HTTP 性能经常用 ab，那测试带宽本身，一般用什么工具呢？</p></li><li><p>要把 TIME_WAIT 停留的时间 2MSL 改小，你知道用什么方法吗？</p></li></ul><p>欢迎在留言区分享你的答案，也欢迎你把今天的内容分享给更多的朋友。</p><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><p>抓包示例文件：<a href="https://gitee.com/steelvictor/network-analysis/tree/master/22" target="_blank" rel="noreferrer">https://gitee.com/steelvictor/network-analysis/tree/master/22</a></p>`,162)])])}const d=e(i,[["render",p]]);export{h as __pageData,d as default};
